mapper.select:
SELECT count(*) FROM public.nw_knowledge_document_versions v WHERE v.tenant_id = #{tenantId} AND v.kb_id = #{kbId} AND v.status = 'ready' AND v.source_version IN
#{version}
AND v.chunk_count > 0 AND v.chunk_count = ( SELECT count(*) FROM public.knowledge_chunk_values c WHERE c.tenant_id = v.tenant_id AND c.document_id = v.document_id AND c.source_version = v.source_version )

SELECT v.source_version FROM nw_knowledge_document_versions v JOIN nw_knowledge_documents d ON d.tenant_id=v.tenant_id AND d.kb_id=v.kb_id AND d.id=v.document_id WHERE v.tenant_id=#{tenantId} AND v.kb_id=#{kbId} AND d.deleted_at IS NULL
AND v.source_version IN #{version}
AND FALSE
